import os, glob, re

def load():
    d = os.environ.get('RLM_SESSION_DIR', '')
    if not d:
        return {}
    sessions_file = os.path.join(d, '..', 'sessions', os.path.basename(d) + '.jsonl')
    sessions_file = os.path.abspath(sessions_file)
    print(f"Loading from: {sessions_file}")
    try:
        with open(sessions_file, 'r') as f:
            content = f.read()
        G = {}
        for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', content):
            k, h, w = m[1], int(m[2]), int(m[3])
            rows_raw = '\n'.join(content[m.end():].split('\n')[:h])
            rows = [r.split() for r in rows_raw.split('\n')] if '\n' in rows_raw else [[rows_raw]]
            if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
                G[k] = [[int(x) for x in r] for r in rows]
        return G
    except Exception as e:
        print(f"Error: {e}")
        return {}

G = load()
print("Loaded grids:")
for k, v in G.items():
    print(f"  {k}: {v[0]}")

